@startuml

class Game {
  + hiddenTile : Tile
}

class Board {
  + layout : string
}

class Tile {
  + isVisited : boolean
  + isActionTile : boolean
  + turnsRemaining : int
}

class Connection {
  + side : string
}

class ActionCard {
  + type : ActionType
}

class Player {
  + color : string
}

class PlayingPiece {
  + color : string
}

class Die {
}

enum ActionType {
  EXTRA_TURN
  CONNECT_TILES
  REMOVE_CONNECTION
  MOVE_TO_ARBITRARY
  LOSE_TURN
}

Game "1" *-- "1" Board
Game "1" *-- "1" Die
Game "1" *-- "1..32" ActionCard
Board "1" *-- "*" Tile
Board "1" *-- "*" Connection
Tile "1" -- "0..1" Connection : right
Tile "1" -- "0..1" Connection : left
Tile "1" -- "0..1" Connection : top
Tile "1" -- "0..1" Connection : bottom
Game "1" -- "2..4" Player
Player "1" *-- "1" PlayingPiece

@enduml

